package app.bookey.domain.club;
import jakarta.persistence.*; import lombok.*; import java.time.Instant;
@Getter @Entity @Table(name="club_meetings") @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class ClubMeeting { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="club_id",nullable=false) private Long clubId; @Column(name="created_by") private Long createdBy; @Column(nullable=false,length=100) private String title; @Column(length=1000) private String description; @Column(name="starts_at",nullable=false) private Instant startsAt; @Column(name="ends_at") private Instant endsAt; @Column(name="place_name",nullable=false,length=150) private String placeName; @Column(nullable=false,length=300) private String address; private Double latitude; private Double longitude; @Column(name="map_url") private String mapUrl; @Column(name="response_deadline") private Instant responseDeadline; @Column(nullable=false,length=20) private String status="OPEN"; @Column(name="cancelled_at") private Instant cancelledAt;
 /** 이 만남에서 읽을 책(선택) — 다가오는 만남의 책이 모임의 지금 읽는 책이 된다. */ @Column(name="book_id") private Long bookId;
 /** 최대 인원(선택) — null 이면 제한 없이 받는다. */ @Column(name="max_attendees") private Integer maxAttendees;
 public ClubMeeting(Long c,Long u,String t,String d,Instant s,Instant e,String p,String a,Double lat,Double lng,String map,Instant deadline,Long book,Integer max){clubId=c;createdBy=u;update(t,d,s,e,p,a,lat,lng,map,deadline,book,max);} public void update(String t,String d,Instant s,Instant e,String p,String a,Double lat,Double lng,String map,Instant deadline,Long book,Integer max){title=t.trim();description=d;startsAt=s;endsAt=e;placeName=p.trim();address=a.trim();latitude=lat;longitude=lng;mapUrl=map;responseDeadline=deadline;bookId=book;maxAttendees=max;}
 /** 정원이 찼는지 — 제한이 없으면 늘 false. */ public boolean isFull(long attendeeCount){return maxAttendees!=null&&attendeeCount>=maxAttendees;} public void cancel(){status="CANCELLED";cancelledAt=Instant.now();} public boolean isOpen(){return "OPEN".equals(status);} }
